export const AIVAR_FAQ_BODY = "<section class=\"block\" id=\"faq\">\n  <div class=\"wrap faq-grid\">\n    <div><h2 class=\"split\">Questions, answered.</h2><p class=\"lede\" style=\"margin-top:18px\">Can't find what you need? Send us a message and the right team will reply.</p><button class=\"btn btn-ghost\" style=\"margin-top:24px\" data-enquire=\"Something else\">Ask a question</button></div>\n    <div class=\"faq\">\n      <details><summary>How do I place a bulk or wholesale order?<i></i></summary><p class=\"ans\">Add products and quantities to your enquiry list and send it, or use the contact form. The supply team will share pricing based on volume and location.</p></details>\n      <details><summary>Can I customise corporate gift boxes?<i></i></summary><p class=\"ans\">Yes. Use the gift builder to choose a box, pick the contents and add a logo sleeve or greeting card. For fully custom boxes, request a quote.</p></details>\n      <details><summary>Do you work with buyers outside India?<i></i></summary><p class=\"ans\">Send an export or private-label enquiry with your country, products and expected volumes, and our team will come back with options.</p></details>\n      <details><summary>When does supply start?<i></i></summary><p class=\"ans\">We are preparing to open supply. Send an enquiry now and our team will contact you with pricing and availability as soon as orders open.</p></details>\n      <details><summary>How can I support AIVAR Foundation?<i></i></summary><p class=\"ans\">Choose \"Pledge support\" in the Foundation section, or tick the Foundation box when you send an enquiry. Companies can also sponsor meals as part of CSR plans.</p></details>\n      <details><summary>Can I hire staff for a short period?<i></i></summary><p class=\"ans\">Yes. AIVAR Workforce offers short-term staff for events and festive peaks, contract staffing and permanent placement.</p></details>\n    <details><summary>Can I get custom food packaging in small quantities?<i></i></summary><p class=\"ans\">Yes. Share your product and expected volumes and we will recommend a format, including smaller trial runs before a full production order.</p></details><details><summary>Do you supply schools and government institutions?<i></i></summary><p class=\"ans\">Yes, institutional supply covers corporate offices, schools, colleges and government kitchens. Share your location and headcount for a plan.</p></details></div>\n  </div>\n</section><section class=\"block\" id=\"faq-cta\" style=\"padding-top:0\">\n  <div class=\"wrap\">\n    <div class=\"cta-band\">\n      <div>\n        <h2 class=\"split\">Still stuck?</h2>\n        <p class=\"lede\" style=\"margin-top:14px\">Message us directly or try IVA on WhatsApp for a quick answer.</p>\n      </div>\n      <div class=\"cta-btns\">\n        <a class=\"btn btn-primary\" href=\"/contact\">Contact us</a>\n        <a class=\"btn btn-ghost\" href=\"/whatsapp\">Chat with IVA</a>\n      </div>\n    </div>\n  </div>\n</section>\n";
